    xmlXPathObjectPtr result = xmlXPathEvalExpression(xpath_expr, context);
    free(xpath_expr);

    if (!result || !result->nodesetval || result->nodesetval->nodeNr == 0) {
        xmlXPathFreeObject(result);
        xmlXPathFreeContext(context);
        xmlFreeDoc(doc);
        return NULL;
    }

    xmlNodePtr node = result->nodesetval->nodeTab[0];
    xmlXPathFreeObject(result);
    xmlXPathFreeContext(context);
    xmlFreeDoc(doc);

    StudentInfo* student = (StudentInfo*)malloc(sizeof(StudentInfo));
    student->name = (char*)xmlGetProp(node, (const char*)"name");
    student->age = (char*)xmlGetProp(node, (const char*)"age");
    student->citizenship = (char*)xmlGetProp(node, (const char*)"citizenship");

    return student;
}
