typedef struct {
    char* name;
    char* age;
    char* citizenship;
} StudentInfo;

StudentInfo* get_student_info(const char* xml_data, const char* username, const char* password) {
    xmlDocPtr doc = xmlParseMemory(xml_data, strlen(xml_data));
    if (!doc) {
        return NULL;
    }

    xmlXPathContextPtr context = xmlXPathNewContext(doc);
    if (!context) {
        xmlFreeDoc(doc);
        return NULL;
    }

    char* xpath_expr = (char*)malloc(256);
    snprintf(xpath_expr, 256, "//student[username='%s' and password='%s']", username, password);
    xmlXPathObjectPtr result = xmlXPathEvalExpression(xpath_expr, context);
    free(xpath_expr);

    if (!result || !result->nodesetval || result->nodesetval->nodeNr == 0) {
        xmlXPathFreeObject(result);
        xmlXPathFreeContext(context);
